import java.util.List;
import java.util.NoSuchElementException;
import java.util.Optional;
import java.util.concurrent.atomic.AtomicInteger;

public class Main {
    record Address(String city) {}
    record User(String id, String name, Address address) {}

    static User legacyFindUser(String id) {
        // 模拟历史接口：返回 null 表示未找到
        return switch (id) {
            case "42" -> new User("42", "Ada", new Address("Shanghai"));
            case "43" -> new User("43", "Bob", null);
            default -> null;
        };
    }

    static Optional<User> findUser(String id) {
        // ofNullable 包裹可能为 null 的历史接口
        return Optional.ofNullable(legacyFindUser(id));
    }

    static String expensiveDefault(AtomicInteger calls) {
        calls.incrementAndGet();
        return "Unknown";
    }

    public static void main(String[] args) {
        // 1) map 链：任何一环为空都安全落入默认值
        String city = findUser("42")
            .map(User::address)       // User -> Address
            .map(Address::city)       // Address -> String
            .filter(name -> name.length() > 3)  // 过滤短名称
            .orElse("N/A");
        System.out.println("city: " + city);  // Shanghai

        // 2) flatMap：address 本身可能为 null，用 flatMap 压平
        String missingCity = findUser("43")
            .flatMap(user -> Optional.ofNullable(user.address()))
            .map(Address::city)
            .orElseGet(() -> "Unknown");  // 惰性求值
        System.out.println("missing city: " + missingCity);  // Unknown

        // 3) Stream + Optional：findFirst 自然返回 Optional
        Optional<String> firstLongName = List.of("Li", "Ada", "Grace").stream()
            .filter(name -> name.length() >= 4)
            .findFirst();
        System.out.println("first long name: " + firstLongName.orElseThrow());  // Grace

        // 4) orElse vs orElseGet 求值时机差异
        AtomicInteger calls = new AtomicInteger();
        String eager = Optional.of("present").orElse(expensiveDefault(calls));   // 立即求值
        String lazy  = Optional.of("present").orElseGet(() -> expensiveDefault(calls)); // 惰性
        String fallback = Optional.<String>empty().orElseGet(() -> expensiveDefault(calls));
        // calls=2：orElse 执行 1 次 + orElseGet 在 empty 时执行 1 次
        System.out.println("defaults: eager=" + eager + " lazy=" + lazy
            + " fallback=" + fallback + " calls=" + calls.get());

        // 5) of(null) 立即抛 NPE——在创建点暴露违反契约
        boolean ofNullThrows = false;
        try {
            Optional.of(null);
        } catch (NullPointerException e) {
            ofNullThrows = true;
        }

        // 6) empty().get() 抛 NoSuchElementException——应用 orElseThrow 替代
        boolean emptyGetThrows = false;
        try {
            Optional.empty().get();
        } catch (NoSuchElementException e) {
            emptyGetThrows = true;
        }

        // 7) ifPresentOrElse 处理有值和空两个分支
        AtomicInteger branch = new AtomicInteger();
        findUser("404").ifPresentOrElse(
            user -> branch.set(1),
            () -> branch.set(-1)
        );

        assert city.equals("Shanghai");
        assert missingCity.equals("Unknown");
        assert firstLongName.orElseThrow().equals("Grace");
        assert eager.equals("present");
        assert lazy.equals("present");
        assert fallback.equals("Unknown");
        assert calls.get() == 2;
        assert ofNullThrows;
        assert emptyGetThrows;
        assert branch.get() == -1;
    }
}
